SaveSetting(ENABLED_KEYS[Kind], S.Kinds[Kind].Enabled)
if IsEnabled(Kind) then
S.Timer = SCAN_INTERVAL
else
Clear(Kind)
end
end
local function Rebuild(Kind)
Clear(Kind)
