	["Features/FollowerGuard.lua"] = [======[
return {
Name = "FollowerGuard",
IsFeature = true,
Dependencies = {"Runtime", "SaveConfig", "Components", "ProfileManager", "AutoBlock"},
Start = function(Context)
local Services = Context.Services
local Players = Services.Players
local HttpService = Services.HttpService
local Player = Context.Player
local Feature = Context.Feature
local CONFIG = Context.CONFIG
local AICFeature = Context.AICFeature
local AICUI = Context.AICUI
local AICProfile = Context.AICProfile
local NotifyAction = Context.NotifyAction
local UIRef = Context.UIRef
local FOLLOWER_WINDOW = 30 * 60
local FOLLOWER_TRIP_SIGHTINGS = 2
local FOLLOWER_RETRIP_COOLDOWN = 60
local SIGHTING_DEDUPE = 60
local FOLLOWER_KEEP = 24 * 60 * 60
local FOLLOWER_FILE = Context.PROFILE_FOLDER .. "/FollowerLog.json"
local FOLLOWER_FILE_VERSION = 1
local FollowerGuard = {
Name = "FollowerGuard",
IsFeature = true,
S = {
Sightings = {},
Latched = false,
LatchedAt = 0,
LatchedBy = {},
CountFrom = 0,
Tripped = {},
Scanned = false,
WasEnabled = nil,
SaveQueued = false,
NoticeAt = 0,
},
}
local S = FollowerGuard.S
local function IsExempt(OtherPlayer)
if OtherPlayer == Player then
return true
end
if AICFeature.IsWhitelisted ~= nil and AICFeature.IsWhitelisted(OtherPlayer.UserId) == true then
return true
end
local Leader = CONFIG.PARTY_LEADER
return type(Leader) == "table" and tonumber(Leader.UserId) == OtherPlayer.UserId
end
local function NormalizeSightings(Value)
local Result = {}
for _, Entry in ipairs(type(Value) == "table" and Value or {}) do
local UserId = type(Entry.UserId) == "string" and Entry.UserId or nil
local Time = tonumber(Entry.Time)
local JobId = type(Entry.JobId) == "string" and Entry.JobId or nil
local Kind = Entry.Kind
if UserId and Time and JobId and (Kind == "present" or Kind == "joined") then
table.insert(Result, {
UserId = UserId,
Name = type(Entry.Name) == "string" and Entry.Name or UserId,
Time = Time,
JobId = JobId,
Kind = Kind,
})
end
end
return Result
end
local function WriteLog()
if not AICProfile.CanUseFileStorage() then
return false
end
AICProfile.EnsureProfileFolder()
local Now = os.time()
local Kept = {}
for _, Entry in ipairs(S.Sightings) do
if Now - Entry.Time <= FOLLOWER_KEEP then
table.insert(Kept, Entry)
end
end
S.Sightings = Kept
local Success, Raw = pcall(function()
return HttpService:JSONEncode({
Version = FOLLOWER_FILE_VERSION,
Latched = S.Latched,
LatchedAt = S.LatchedAt,
LatchedBy = S.LatchedBy,
CountFrom = S.CountFrom,
Sightings = S.Sightings,
})
end)
if not Success then
warn("AutoFarm follower log encode failed:", Raw)
return false
end
local WriteSuccess, WriteError = pcall(writefile, FOLLOWER_FILE, Raw)
if not WriteSuccess then
warn("AutoFarm follower log save failed:", WriteError)
return false
end
S.SaveQueued = false
return true
end
local function QueueLog()
S.SaveQueued = true
end
Context.Lifetime.OnEnd(function()
if S.SaveQueued then
WriteLog()
end
end)
local function LoadLog()
if not AICProfile.CanUseFileStorage() then
return
end
local CheckSuccess, Exists = pcall(isfile, FOLLOWER_FILE)
if not CheckSuccess or not Exists then
return
end
local Success, Decoded = pcall(function()
return HttpService:JSONDecode(readfile(FOLLOWER_FILE))
end)
if not Success or type(Decoded) ~= "table" then
warn("AutoFarm follower log read failed:", Decoded)
return
end
S.Sightings = NormalizeSightings(Decoded.Sightings)
S.Latched = Decoded.Latched == true
S.LatchedAt = tonumber(Decoded.LatchedAt) or 0
S.LatchedBy = type(Decoded.LatchedBy) == "table" and Decoded.LatchedBy or {}
S.CountFrom = tonumber(Decoded.CountFrom) or 0
end
local function CountSightings(UserId, Now)
local Count = 0
for _, Entry in ipairs(S.Sightings) do
if Entry.UserId == UserId
and Entry.Time >= math.max(S.CountFrom, Now - FOLLOWER_WINDOW)
and Entry.Time <= Now
then
Count += 1
end
end
return Count
end
local function StopFarm()
if AICFeature.S.Enabled then
AICFeature.S.Enabled = false
AICUI.updateButton()
AICProfile.SaveActiveProfile()
end
end
local function HoldInstead(OtherPlayer, Reason)
S.Latched = true
S.LatchedAt = os.time()
S.LatchedBy = { UserId = tostring(OtherPlayer.UserId), Name = OtherPlayer.Name }
QueueLog()
StopFarm()
NotifyAction(
"FOLLOWER GUARD",
string.format(
"@%s is following you and the game could not be left (%s) - Auto Farm is off until you turn it on",
OtherPlayer.Name,
Reason or "unavailable"
),
8
)
end
local function LeaveGame(OtherPlayer)
if AICFeature.ReportBeforeLeave then
AICFeature.ReportBeforeLeave(OtherPlayer)
end
local Text = "Follower Guard: someone keeps joining your servers"
if OtherPlayer and OtherPlayer.Name then
Text = "Follower Guard: @" .. OtherPlayer.Name .. " keeps joining your servers"
end
local Success, Error = pcall(function()
Player:Kick(Text)
end)
return Success, Error
end
local function Trip(OtherPlayer, Count, Now)
S.Tripped[tostring(OtherPlayer.UserId)] = Now
if Now - S.NoticeAt >= 8 then
S.NoticeAt = Now
NotifyAction(
"FOLLOWER GUARD",
string.format(
"@%s has joined your servers %d times in %d minutes - leaving the game",
OtherPlayer.Name,
Count,
FOLLOWER_WINDOW / 60
),
8
)
end
local function KickFor()
local Left, Error = LeaveGame(OtherPlayer)
if not Left then
HoldInstead(OtherPlayer, "kick failed: " .. tostring(Error))
end
end
local Wait = AICFeature.LeaveDelay and AICFeature.LeaveDelay() or 0
if Wait > 0 then
task.spawn(function()
task.wait(Wait)
if Feature.FollowerGuard.Enabled ~= true then
return
end
KickFor()
end)
return
end
KickFor()
end
local function Evaluate(OtherPlayer, Now)
if not Feature.FollowerGuard.Enabled then
return
end
local UserId = tostring(OtherPlayer.UserId)
local LastTrip = S.Tripped[UserId]
if LastTrip and Now - LastTrip < FOLLOWER_RETRIP_COOLDOWN then
return
end
local Count = CountSightings(UserId, Now)
if Count >= FOLLOWER_TRIP_SIGHTINGS then
Trip(OtherPlayer, Count, Now)
end
end
local function Observe(OtherPlayer, Kind)
if not Feature.FollowerGuard.Enabled or IsExempt(OtherPlayer) then
return
end
local Now = os.time()
local UserId = tostring(OtherPlayer.UserId)
local JobId = tostring(game.JobId or "")
local LastPair
for _, Entry in ipairs(S.Sightings) do
if Entry.UserId == UserId and Entry.JobId == JobId then
if Kind == "present" then
return
end
LastPair = Entry
end
end
if Kind == "joined" and LastPair and Now - LastPair.Time <= SIGHTING_DEDUPE then
return
end
table.insert(S.Sightings, {
UserId = UserId,
Name = OtherPlayer.Name,
Time = Now,
JobId = JobId,
Kind = Kind,
})
QueueLog()
Evaluate(OtherPlayer, Now)
end
local function ScanRoster()
for _, OtherPlayer in ipairs(Players:GetPlayers()) do
Observe(OtherPlayer, "present")
end
end
Context.Connect(Players.PlayerAdded, function(OtherPlayer)
if S.Scanned then
Observe(OtherPlayer, "joined")
end
end)
AICFeature.NotifyManualAutoFarmToggle = function(Value)
if not Value then
return
end
S.Latched = false
S.LatchedAt = 0
S.LatchedBy = {}
S.CountFrom = os.time()
table.clear(S.Tripped)
QueueLog()
end
function FollowerGuard:Update()
if not S.Scanned then
S.Scanned = true
end
local Enabled = Feature.FollowerGuard.Enabled == true
if Enabled and S.WasEnabled ~= true then
ScanRoster()
end
S.WasEnabled = Enabled
if S.Latched and AICFeature.S.Enabled then
StopFarm()
end
if S.SaveQueued then
WriteLog()
end
end
LoadLog()
AICUI.BindFeatureToggle("FollowerGuard", "Follower Guard", function(Enabled)
if Enabled then
ScanRoster()
end
end, UIRef.ServerSafetySection)
if UIRef.ServerSafetySection then
UIRef.ServerSafetySection:AddNote("Kicks you out of the game when one player keeps joining yours")
end
return FollowerGuard
end,
}
]======],
	["Features/FpsBoost.lua"] = [======[
return {
Name = "FpsBoost",
Dependencies = {"Runtime", "SaveConfig", "Components"},
Start = function(Context)
local FeatureState = Context.Feature
local AICUI = Context.AICUI
local AICCombatUtils = Context.AICCombatUtils
local UIRef = Context.UIRef
local Lighting = game:GetService("Lighting")
local REAPPLY_INTERVAL = 5
local SCAN_BATCH = 2000
local FOG_END = 1e6
local OBJECT_RULES = {
{ Class = "ParticleEmitter", Props = { Enabled = false } },
{ Class = "Trail", Props = { Enabled = false } },
{ Class = "Beam", Props = { Enabled = false } },
{ Class = "Smoke", Props = { Enabled = false } },
{ Class = "Fire", Props = { Enabled = false } },
{ Class = "Sparkles", Props = { Enabled = false } },
{ Class = "Light", Props = { Enabled = false } },
{ Class = "Explosion", Props = { Visible = false } },
{ Class = "Decal", Props = { Transparency = 1 } },
{ Class = "BasePart", Props = { CastShadow = false } },
{ Class = "Clouds", Props = { Enabled = false } },
{ Class = "PostEffect", Props = { Enabled = false } },
{ Class = "Atmosphere", Props = { Density = 0, Haze = 0, Glare = 0 } },
}
local LIGHTING_PROPS = {
GlobalShadows = false,
FogEnd = FOG_END,
ShadowSoftness = 0,
EnvironmentDiffuseScale = 0,
EnvironmentSpecularScale = 0,
}
local TERRAIN_PROPS = {
WaterWaveSize = 0,
WaterWaveSpeed = 0,
WaterReflectance = 0,
Decoration = false,
}
local S = {
Saved = setmetatable({}, { __mode = "k" }),
Connections = {},
Token = 0,
QualitySaved = nil,
}
local Feature = { Name = "FpsBoost", S = S }
local function SetProp(Object, Property, Value)
local Saved = S.Saved[Object]
if not Saved then
Saved = {}
S.Saved[Object] = Saved
end
if Saved[Property] == nil then
local Success, Current = pcall(function()
return Object[Property]
end)
if not Success or Current == nil then
return
end
Saved[Property] = Current
end
pcall(function()
Object[Property] = Value
end)
end
local function IsOurs(Object)
local Folder = AICCombatUtils.S.DebugFolder
return Folder ~= nil and (Object == Folder or Object:IsDescendantOf(Folder))
end
local function ApplyObject(Object)
if typeof(Object) ~= "Instance" or not Object.Parent or IsOurs(Object) then
return
end
for _, Rule in ipairs(OBJECT_RULES) do
if Object:IsA(Rule.Class) then
for Property, Value in pairs(Rule.Props) do
SetProp(Object, Property, Value)
end
return
end
end
end
local function ApplyLighting()
for Property, Value in pairs(LIGHTING_PROPS) do
SetProp(Lighting, Property, Value)
end
local Terrain = workspace:FindFirstChildOfClass("Terrain")
if Terrain then
for Property, Value in pairs(TERRAIN_PROPS) do
SetProp(Terrain, Property, Value)
end
end
end
local function SetQuality(Level)
pcall(function()
local Rendering = settings().Rendering
if S.QualitySaved == nil then
S.QualitySaved = Rendering.QualityLevel
end
Rendering.QualityLevel = Level
end)
end
local function RestoreQuality()
local Level = S.QualitySaved
S.QualitySaved = nil
if Level ~= nil then
pcall(function()
settings().Rendering.QualityLevel = Level
end)
end
end
local function ScanAll(Token, Roots)
for _, Root in ipairs(Roots) do
local List = Root:GetDescendants()
for Index, Object in ipairs(List) do
if S.Token ~= Token or not Context.Lifetime.Alive then
return
end
ApplyObject(Object)
if Index % SCAN_BATCH == 0 then
task.wait()
end
end
end
end
local STREAM_BATCH = 500
local PendingObjects = {}
local PendingScheduled = false
local function FlushPending(Token)
PendingScheduled = false
if S.Token ~= Token or not FeatureState.FpsBoost.Enabled then
return
end
local Batch = PendingObjects
PendingObjects = {}
for Index, Object in ipairs(Batch) do
if S.Token ~= Token then
return
end
if Index > STREAM_BATCH then
for Rest = Index, #Batch do
table.insert(PendingObjects, Batch[Rest])
end
break
end
if Object.Parent then
ApplyObject(Object)
end
end
if #PendingObjects > 0 and not PendingScheduled then
PendingScheduled = true
task.delay(0, FlushPending, Token)
end
end
local function OnAdded(Object)
if not FeatureState.FpsBoost.Enabled then
return
end
table.insert(PendingObjects, Object)
if not PendingScheduled then
PendingScheduled = true
task.delay(0, FlushPending, S.Token)
end
end
function Feature.Enable()
S.Token += 1
local Token = S.Token
Context.Lifetime.Disconnect(S.Connections)
table.insert(S.Connections, workspace.DescendantAdded:Connect(OnAdded))
table.insert(S.Connections, Lighting.DescendantAdded:Connect(OnAdded))
ApplyLighting()
SetQuality(Enum.QualityLevel.Level01)
task.spawn(ScanAll, Token, { Lighting, workspace })
task.spawn(function()
while Context.Lifetime.Alive and S.Token == Token do
task.wait(REAPPLY_INTERVAL)
if Context.Lifetime.Alive and S.Token == Token then
ApplyLighting()
end
end
end)
end
function Feature.Disable()
S.Token += 1
Context.Lifetime.Disconnect(S.Connections)
for Object, Saved in pairs(S.Saved) do
for Property, Value in pairs(Saved) do
pcall(function()
Object[Property] = Value
end)
end
end
table.clear(S.Saved)
table.clear(PendingObjects)
RestoreQuality()
end
AICUI.BindFeatureToggle("FpsBoost", "FPS Boost", function(Enabled)
if Enabled then
Feature.Enable()
else
Feature.Disable()
end
end, UIRef.UtilitySection)
if FeatureState.FpsBoost.Enabled then
Feature.Enable()
end
Context.Lifetime.OnEnd(Feature.Disable)
return Feature
end,
}
